class MessageBubbleManager {

        static initialize() {
            this._queue = [];
        }

        static add_MessageBubble(message) {
            var _message = message;
            var new_MessageBubble = new MessageBubble(_message);
            this._queue.push(new_MessageBubble)
        }

        static remove_MessageBubble(bubble) {
            for (var i = 0; i < this._queue.length; i++) {
                if (this._queue[i] == bubble) {
                    this._queue.splice(i, 1);
                }
            }
        }

        static _giveOrder() {
            for (var i = 0; i < this._queue.length; i++) {
                this._queue[i]._order = i;
            }
        }
    }

    class MessageBubble extends Sprite {
        constructor(message) {
            super();
            this._order = 0;
            this._state = "";
            this._message = message;
            this._duration = 200;
            this._timer = 0;
            this._bitmap = "";
            this._x = 0;
            this._y = 0;

            this._init();
        }

        _init() {
            this._messageWidth = this.calculateEffectiveLength(this._message);
            this._bitmap = ImageManager.loadPicture("UI/messageBubble_s");
            this._bitmap.addLoadListener(() => {
                this._body = new Sprite(this._bitmap);
                this._body.anchor.set(0.5);

                this._text = new Sprite(new Bitmap(this._body.width, this._body.height));
                this._text.bitmap.drawText(this._message, 0, 0, this._body.width, this._body.height, 'center');
                this._text.anchor.set(0.5);

                this.addChild(this._body);
                this.addChild(this._text);
                SceneManager._scene.addChild(this);

                this._updatePosition();
            });
        }

        update() {
            this._timer += 1;

            this._updatePosition();
            this._updateAnimation();

            super.update();
        }

        _updatePosition() {
            MessageBubbleManager._giveOrder();

            var padding = 4;
            var margin = 6;
            var heightUnit = this._body.height + margin;
            var targetPosX = Graphics.width - (this._body.width / 2) - padding;
            var targetPosY = (this._order + 0.5) * heightUnit + padding;

            this.x = targetPosX;
            this.y = this.y * 0.9 + targetPosY * 0.1;
            this._x = this.x;
            this._y = this.y;
        }

        _updateAnimation() {
            //simpleFade in out animation with opacity and scale
            var animationTiming = this._timer/ this._duration;
            var animationMultiplier = Math.max( (30 - this._timer) / 30, 0 );
            this.scale.x = 1 + Math.sin(animationMultiplier * Math.PI * 5) * animationMultiplier * 0.1;
            this.scale.y = 1 + Math.cos(animationMultiplier * Math.PI * 5) * animationMultiplier * 0.1;
            if (this._timer >= this._duration - 20) {
            this.opacity -= 255 / 20;
            }
            if (this.opacity <= 0) {
                MessageBubbleManager.remove_MessageBubble(this)
                this.destroy();
            }
        }
    }
